  const byUuid = new Map(rows.filter((row) => row?.id).map((row) => [String(row.id), row]));
  const rowsByCode = new Map<string, any[]>();
  rows.forEach((row) => {
    const code = String(row?.tree_id ?? '').trim().toLowerCase();
